mapper.sql:
WITH project_mm AS (
  SELECT a.dev_id,m.work_ym,sum(m.mm_qty) AS mm
  FROM asgn.asgn a JOIN asgn.asgn_mth m ON m.asgn_id=a.asgn_id
  WHERE a.prj_id=#{projectId} AND a.asgn_stts_cd!='CANCELLED' AND m.work_ym <= #{month}
  GROUP BY a.dev_id,m.work_ym
), closed AS (
  SELECT c.cst_ym AS month,sum(c.lbr_cst_amt::numeric+c.drct_expns_amt) AS amount
  FROM cst.cst_aloc c JOIN fin.mth_cls f ON f.cls_ym=c.cst_ym AND f.cls_stts_cd='CLOSED'
  WHERE c.prj_id=#{projectId} AND c.cst_ym <= #{month} GROUP BY c.cst_ym
)
